<script setup>
import { confirmAction } from '@/lib/confirm-action.js';
import {ref,computed,watch,onMounted,onBeforeUnmount} from 'vue';
import {useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router';
import {useLearning} from '@/store.js';
import {curriculumApi} from '@/services/curriculum.js';
import {modelApi} from '@/services/models.js';
import {planningApi} from '@/services/planning.js';
import {sameAgentRoute} from '@/lib/planningRoute.js';
import {planningStep} from '@/lib/planning-progress.js';
import {useModelJob} from '@/lib/useModelJob.js';
import {ArrowLeft,ArrowUpRight,Check,LoaderCircle,Play,RefreshCw,Save,Square,X} from '@/components/app/icons.js';
const route=useRoute(),router=useRouter(),store=useLearning();
const selectedActivity=ref('');
const activeActivity=computed(()=>edited.value?.blocks.find(b=>b.id===selectedActivity.value)||edited.value?.blocks[0]);
const outputTab=ref('plan'),lessonId=ref(String(route.query.lesson||store.data.lesson?.id||'')),lesson=ref(null),catalog=ref([]),history=ref([]),task=ref(''),taskType=ref('auto'),constraints=ref('');
const edited=ref(null),dirty=ref(false),saving=ref(false),loading=ref(true),error=ref(''),notice=ref(''),confirmOpen=ref(false),draftState=ref(null),reading=ref(false);
let disposed=false,lessonGeneration=0,routeGeneration=0;
const types=[{value:'auto',label:'自动识别任务'},{value:'activity',label:'活动设计'},{value:'misconception',label:'误解纠正'},{value:'foundation',label:'补基础'}];
const stages=[['context','理解任务与课时'],['cases','检索教学案例'],['materials','定位原文材料'],['generate','生成备课建议'],['validate','核验结构与依据'],['ready','等待教师确认']];
const clone=value=>JSON.parse(JSON.stringify(value));
const {job,busy,error:jobError,create,open,retry}=useModelJob(value=>{if(disposed)return;const plan=value.result?.editable||value.result?.plan;if(plan&&!dirty.value)edited.value=clone(plan);});
const result=computed(()=>job.value?.result);
const sourceConflict=computed(()=>job.value&&lesson.value&&job.value.input.lesson?.versionId!==lesson.value.versionId);
const options=computed(()=>catalog.value.flatMap(c=>c.units.flatMap(u=>u.lessons.filter(l=>l.published).map(l=>({value:l.id,label:c.title+' / '+l.title})))));
const canEdit=computed(()=>!!edited.value&&!busy.value&&!saving.value&&!result.value?.accepted&&job.value?.status!=='cancelled');
const materialGroups=computed(()=>{const groups=new Map();for(const item of result.value?.materials||[]){if(!groups.has(item.unitId))groups.set(item.unitId,{...item,excerpts:[]});groups.get(item.unitId).excerpts.push(item)}return [...groups.values()]});
const stepFor=key=>planningStep(result.value,key);
const statusName=value=>({queued:'排队中',running:'执行中',succeeded:'已完成',failed:'失败',cancelled:'已取消'}[value]||'待执行');
const evidenceFor=ids=>(result.value?.evidence||[]).filter(e=>ids.includes(e.id));
async function selectLesson(id){const generation=++lessonGeneration;lesson.value=null;error.value='';try{const value=await curriculumApi.lesson(id);if(!disposed&&generation===lessonGeneration)lesson.value=value}catch(e){if(generation===lessonGeneration)error.value=e.message}}
async function historyLoad(){history.value=(await modelApi.list()).filter(j=>j.capability==='lesson_agent');}
async function chooseJob(id){await router.push({query:{lesson:history.value.find(j=>j.id===id)?.lessonId||lessonId.value,job:id}});}
async function changeLesson(id){await router.push({query:{lesson:id}});}
async function start(blockId=null,quality=false){if(busy.value||saving.value)return;error.value='';notice.value='';if(!task.value.trim()){error.value='请填写教学任务。';return}if(!lesson.value){error.value='请选择已发布课时。';return}if((blockId||quality)&&!(await saveEdits()))return;if(!(await store.save())){error.value=store.saveError;return}const qualityParent=job.value?.id,rewriteTarget=route.query.block||job.value?.input?.regenerateBlockId;edited.value=null;dirty.value=false;const data=blockId?{lessonId:job.value.input.lessonId,task:task.value.trim(),taskType:taskType.value,constraints:constraints.value,parentJobId:job.value.id,regenerateBlockId:blockId}:{lessonId:lessonId.value,task:task.value.trim(),taskType:taskType.value,constraints:constraints.value,...(quality?{qualityRevisionOf:qualityParent}:{}),...(rewriteTarget?{rewriteBlockId:String(rewriteTarget)}:{})};await create({capability:'lesson_agent',data});if(job.value){await router.replace({query:{lesson:lessonId.value,job:job.value.id,...(rewriteTarget?{block:String(rewriteTarget)}:{})}});await historyLoad()}}
async function saveEdits(){if(!edited.value||saving.value)return false;saving.value=true;error.value='';try{const value=await planningApi.save(job.value.id,edited.value);dirty.value=false;await open(value);notice.value='建议草稿已保存';return true}catch(e){error.value=e.message;return false}finally{saving.value=false}}
async function prepareConfirmation(){if(!(await saveEdits()))return;reading.value=true;try{draftState.value=await planningApi.currentDraft(job.value.input.lessonId);confirmOpen.value=true}catch(e){error.value=e.message}finally{reading.value=false}}
async function confirmDraft(){if(saving.value)return;saving.value=true;error.value='';store.externalUpdating=true;try{while(store.saving)await new Promise(r=>setTimeout(r,20));await planningApi.confirm(job.value.id,draftState.value.draftHash);await store.load(job.value.input.lessonId,true);await open(await modelApi.detail(job.value.id));confirmOpen.value=false;notice.value='已保存到备课草稿，尚未发布'}catch(e){error.value=e.message}finally{store.externalUpdating=false;saving.value=false}}
async function cancel(){if(saving.value)return;saving.value=true;try{await open(await planningApi.cancel(job.value.id));await historyLoad();notice.value='任务已取消，已完成结果保留'}catch(e){error.value=e.message}finally{saving.value=false}}
function beforeUnload(event){if(dirty.value){event.preventDefault();event.returnValue=''}}
async function loadRoute(){
 const generation=++routeGeneration;loading.value=true;selectedActivity.value='';edited.value=null;dirty.value=false;error.value='';notice.value='';await open(null);
 try{
  if(route.query.job){const value=await modelApi.detail(String(route.query.job));if(disposed||generation!==routeGeneration)return;if(value.capability!=='lesson_agent')throw Error('这不是备课任务。');if(route.query.lesson!==value.input.lessonId){await router.replace({query:{...route.query,lesson:value.input.lessonId}});return}lessonId.value=value.input.lessonId;task.value=value.input.task;taskType.value=value.input.taskType;constraints.value=value.input.constraints;await selectLesson(lessonId.value);if(generation===routeGeneration)await open(value)}
  else{lessonId.value=String(route.query.lesson||store.data.lesson?.id||options.value[0]?.value||'');task.value=route.query.block?'改写当前活动的讲解，补充教师追问与学生回应建议，保留其余内容':'';constraints.value='';taskType.value='auto';await selectLesson(lessonId.value)}
 }catch(e){if(generation===routeGeneration)error.value=e.message}finally{if(generation===routeGeneration)loading.value=false}
}
watch(()=>[route.query.job,route.query.lesson],loadRoute);
onMounted(async()=>{window.addEventListener('beforeunload',beforeUnload);try{catalog.value=await curriculumApi.catalog();await historyLoad();await loadRoute()}catch(e){error.value=e.message;loading.value=false}});
onBeforeRouteUpdate(async (to,from)=>{if(sameAgentRoute(to.query,from.query))return true;if(saving.value)return false;return !dirty.value||await confirmAction('切换任务会放弃未保存的建议修改，继续？')});
onBeforeRouteLeave(async ()=>!saving.value&&(!dirty.value||await confirmAction('建议修改尚未保存，仍然离开？')));
onBeforeUnmount(()=>{disposed=true;window.removeEventListener('beforeunload',beforeUnload)});
</script>
<template>
<PageHeading title="任务备课"><RouteButton :route="'prepare?lesson='+lessonId" secondary><ArrowLeft :size="16"/>我的教案</RouteButton><AppButton v-if="edited&&!result?.accepted&&job?.status!=='cancelled'" variant="outline" :disabled="!canEdit" @click="saveEdits"><Save :size="16"/>{{ saving?'保存中…':'保存建议' }}</AppButton><AppButton v-if="edited&&!result?.accepted&&job?.status!=='cancelled'" :disabled="!canEdit||reading||sourceConflict" @click="prepareConfirmation">确认用于备课</AppButton><Status v-if="result?.accepted" tone="green">已保存到备课</Status></PageHeading>
<AppAlert type="error" v-if="error||jobError" class="form-error" role="alert">{{ error||jobError }}</AppAlert><AppAlert type="success" v-if="notice" class="library-notice" role="status">{{ notice }}</AppAlert><AppAlert type="error" v-if="sourceConflict" class="form-error" role="alert">来源课时已变化：此任务使用 v{{ job.input.lesson.version }}，当前发布 v{{ lesson.version }}。历史结果保留；请选择当前课时重新生成。</AppAlert><ElSkeleton v-if="loading" animated :rows="3" aria-label="读取中…"/>
<div class="planning-workbench" :class="{'teacher-agent-new':!job}" v-else>
<Surface data-ui="card" class="planning-input"><AppDisclosure class="teacher-agent-input" :open="!job"><template #title>{{ job?'修改任务':'新建备课任务' }}</template><ElForm @submit.prevent="start()"><label class="field-label">当前课时<AppSelect :model-value="lessonId" label="备课课时" :options="options" :disabled="busy||saving" @update:model-value="changeLesson"/></label><label class="field-label" for="agent-task">教学任务</label><Textarea id="agent-task" v-model="task" :disabled="busy||saving" placeholder="描述本课目标、学生困难或需要的教学活动"/><AppDisclosure class="teacher-agent-options"><template #title>任务类型与限制</template><label class="field-label">任务类型<AppSelect v-model="taskType" label="任务类型" :options="types" :disabled="busy||saving"/></label><label class="field-label" for="agent-constraints">教学限制</label><Textarea id="agent-constraints" v-model="constraints" :disabled="busy||saving" placeholder="课时、材料或学生情况"/></AppDisclosure><AppButton type="submit" :disabled="busy||saving||!lesson||!task.trim()"><LoaderCircle v-if="busy" class="model-spinner" :size="16"/><Play v-else :size="16"/>{{ busy?'执行中…':'开始备课' }}</AppButton></ElForm></AppDisclosure>
<Surface data-ui="card" v-if="lesson&&job" class="planning-lesson"><header><h2>{{ lesson.title }}</h2><Status>v{{ lesson.version }}</Status></header><p>{{ lesson.grade }} 　 {{ lesson.subject }}</p><InfoTip label="课时目标">{{lesson.goal}}</InfoTip></Surface><AppDisclosure class="planning-history"><template #title>备课记录</template><AppButton :variant="(item.id===job?.id)?'selected':'ghost'" data-layout="row" type="button" v-for="item in history" :key="item.id" :class="{active:item.id===job?.id}" :disabled="saving" @click="chooseJob(item.id)"><strong>{{ item.summary||'教学任务' }}</strong><span>{{ statusName(item.status) }} 　 {{ new Date(item.createdAt).toLocaleDateString('zh-CN') }}</span></AppButton><p v-if="!history.length">暂无备课记录</p></AppDisclosure></Surface>
<main v-if="job" class="planning-output"><AppTabs v-model="outputTab" :items="[{value:'plan',label:'备课建议'},{value:'sources',label:'依据与核验'},{value:'process',label:'执行进度'}]"/><Surface v-if="outputTab==='process'||busy" class="planning-process"><div class="planning-section-heading"><h2>执行过程</h2><Status v-if="job">{{ statusName(job.status) }}</Status><AppButton v-if="job&&['queued','running','succeeded'].includes(job.status)&&!result?.accepted" variant="ghost" :disabled="saving" @click="cancel"><Square :size="14"/>{{ busy?'取消任务':'不采用' }}</AppButton><AppButton v-if="job?.status==='failed'" variant="outline" :disabled="busy" @click="retry"><RefreshCw :size="14"/>继续失败步骤</AppButton></div><ElSteps direction="vertical" class="planning-steps"><ElStep v-for="([key,label],i) in stages" :key="key" :title="label" :status="key==='ready'&&!result?.accepted?'wait':({succeeded:'success',failed:'error',running:'process'})[stepFor(key)?.status]||'wait'"><template #description><AppDisclosure :open="stepFor(key)?.status==='failed'"><template #title>{{key==='ready'&&!result?.accepted?'待确认':statusName(stepFor(key)?.status)}}</template><div v-if="stepFor(key)" class="planning-step-details"><p v-if="key==='context'">{{ result.context?.taskLabel }} 　 {{ result.context?.lessonTitle }}</p><p v-else-if="key==='cases'">{{ result.cases?.length||0 }} 篇案例；保留来源版本</p><p v-else-if="key==='materials'">{{ result.materials?.length||0 }} 处原文及当前课时依据</p><p v-else-if="key==='generate'">{{ stepFor(key).output?.origin||'正在调用模型' }}</p><p v-else-if="key==='validate'">{{stepFor(key).reviewedAfterEdit?'教师修订后已重新核验结构、引用和列出的数学关系':'结构与引用由程序核验，教学适用性需教师核对'}}</p><p v-else>{{result?.accepted?'已由教师确认保存到草稿':'等待教师确认；发布仍需在原备课页操作'}}</p><AppDisclosure v-if="stepFor(key).originalFailure"><template #title>查看原生成失败</template><p>{{stepFor(key).originalFailure.error}}</p><time>{{new Date(stepFor(key).originalFailure.finishedAt).toLocaleTimeString('zh-CN')}}</time></AppDisclosure><AppAlert type="error" v-if="stepFor(key).error" role="alert">{{ stepFor(key).error }}</AppAlert><p v-if="stepFor(key).reusedFrom">沿用原备课任务的这一步结果</p><time>{{ stepFor(key).finishedAt?new Date(stepFor(key).finishedAt).toLocaleTimeString('zh-CN'):new Date(stepFor(key).startedAt).toLocaleTimeString('zh-CN') }}</time><InfoTip label="本步工具">{{ stepFor(key).tool }}</InfoTip></div></AppDisclosure></template></ElStep></ElSteps><AppAlert type="error" v-if="job?.error" role="alert" class="form-error">{{ job.error }}</AppAlert></Surface>
<Surface v-if="edited&&outputTab==='plan'" class="planning-plan"><div class="planning-section-heading"><h2>{{ edited.title }}</h2><Status>模型建议</Status></div><div class="planning-editable"><AppDisclosure class="focus-agent-goal"><template #title>整课目标与设计</template><label class="field-label" for="agent-goal">学习目标</label><Textarea id="agent-goal" v-model="edited.goal" :readonly="!canEdit" @update:model-value="dirty=true"/><AppDisclosure class="planning-rationale"><template #title>设计考虑</template><ul><li v-for="reason in edited.rationale" :key="reason">{{ reason }}</li></ul></AppDisclosure></AppDisclosure><div class="focus-plan-activities"><nav aria-label="建议活动"><AppButton :variant="(activeActivity?.id===block.id)?'selected':'ghost'" data-layout="row" type="button" v-for="(block,index) in edited.blocks" :key="block.id" :class="{active:activeActivity?.id===block.id}" :aria-current="activeActivity?.id===block.id?'step':undefined" @click="selectedActivity=block.id"><span>{{String(index+1).padStart(2,'0')}}</span><strong>{{block.title}}</strong></AppButton></nav><Surface v-for="block in activeActivity?[activeActivity]:[]" :key="block.id" class="planning-block"><header><span>{{ String(edited.blocks.findIndex(b=>b.id===block.id)+1).padStart(2,'0') }}</span><label :for="'agent-title-'+block.id" class="sr-only">活动标题</label><Input :id="'agent-title-'+block.id" v-model="block.title" :readonly="!canEdit" @update:model-value="dirty=true"/><AppButton variant="ghost" size="icon-sm" :aria-label="'重新生成'+block.title" :disabled="!canEdit" @click="start(block.id)"><RefreshCw :size="15"/></AppButton></header><label :for="'agent-content-'+block.id" class="sr-only">{{ block.title }}内容</label><Textarea :id="'agent-content-'+block.id" v-model="block.content" :readonly="!canEdit" @update:model-value="dirty=true"/><AppDisclosure class="planning-teaching-fields"><template #title>学生任务与提问</template><label v-for="(label,key) in {studentTask:'学生任务',teacherQuestion:'关键提问',studentResponse:'预设回应',adjustment:'困难处理'}" :key="key">{{ label }}<Textarea v-model="block[key]" :readonly="!canEdit" @update:model-value="dirty=true"/></label></AppDisclosure><AppDisclosure class="planning-block-evidence"><template #title>本活动依据</template><ElLink :underline="false" v-for="source in evidenceFor(block.evidenceIds)" :key="source.id" :href="source.url" target="_blank" rel="noopener">{{ source.title }}{{ source.label?' 　 '+source.label:'' }}<ArrowUpRight :size="13"/></ElLink></AppDisclosure></Surface></div><AppDisclosure v-if="edited.mathClaims.length" class="planning-math"><template #title>列出的数学关系</template><div v-for="(claim,i) in edited.mathClaims" :key="i"><Input v-model="claim.left" :readonly="!canEdit" :aria-label="'核对关系'+(i+1)+'左侧'" @update:model-value="dirty=true"/><span>=</span><Input v-model="claim.right" :readonly="!canEdit" :aria-label="'核对关系'+(i+1)+'右侧'" @update:model-value="dirty=true"/></div></AppDisclosure></div></Surface><Surface data-ui="card" v-else-if="outputTab==='plan'" class="planning-empty"><h2>{{ busy?'正在组织教学活动':'从当前课时开始' }}</h2><p>{{ busy?job?.step:lesson?.goal||'选择课时并填写教学任务' }}</p></Surface>
<Surface data-ui="card" v-if="outputTab==='sources'" class="planning-evidence"><section><div class="planning-section-heading"><h2>核验与确认</h2><InfoTip label="程序核验范围">只核对结构、引用ID及支持的表达式/单变量方程；条件关系需人工核对，不表示整份教学内容已审定。</InfoTip></div><template v-if="result?.verification"><p><Check :size="15"/>结构完整</p><p><Check :size="15"/>引用可定位</p><Status :tone="result.verification.status==='verified'?'green':'amber'">{{ {verified:'列出的关系已核对',inconsistent:'数学不一致',unverified:'数学需核对'}[result.verification.status] }}</Status></template><p v-else>等待程序核验</p><p>教学适用性待教师确认</p><AppDisclosure v-if="result?.textQuality?.warnings?.length" class="planning-quality" open><template #title>表述检查 　 {{ result.textQuality.warnings.length }}</template><Surface data-ui="card" role="article" v-for="(item,i) in result.textQuality.warnings" :key="i"><strong>{{ item.message }}</strong><p>{{ item.excerpt }}</p><Status v-if="item.origin==='existing'">原有内容</Status></Surface><AppButton v-if="!job?.input?.qualityRevisionOf&&!result?.accepted" variant="outline" :disabled="busy||saving" @click="start(null,true)">定向改进一次</AppButton><p v-else>可继续手动编辑</p></AppDisclosure><AppAlert v-for="warning in result?.warnings||[]" :key="warning" type="warning" class="planning-warning">{{ warning }}</AppAlert></section><section v-if="result?.experienceDecision"><h2>教法选择依据</h2><p>{{result.experienceDecision.notice}}</p><Surface data-ui="card" v-for="item in result.experienceDecision.selected" :key="item.versionId"><p>{{item.reason}}</p><p>{{item.method}}</p><p v-if="item.effectCheck">检查方式：{{item.effectCheck}}</p></Surface></section><section><h2>参考案例</h2><Surface data-ui="card" role="article" v-for="item in result?.cases||[]" :key="item.versionId"><ElLink :underline="false" :href="'/#/case-detail?caseId='+item.id+'&versionId='+item.versionId" target="_blank" rel="noopener"><strong>{{ item.title }}</strong><ArrowUpRight :size="14"/></ElLink><p>v{{ item.version }} 　 {{ {teacher:'教师提供',public:'公开材料整理',team:'团队自编',ai_candidate:'AI辅助候选',unknown:'来源未核验'}[item.provenance?.kind||'unknown'] }}</p></Surface><p v-if="!result?.cases?.length">暂无案例依据</p></section><section><h2>原文材料</h2><Surface data-ui="card" role="article" v-for="source in materialGroups" :key="source.unitId"><ElLink :underline="false" :href="source.url" target="_blank" rel="noopener">{{ source.title }} 　 {{ source.label }}<ArrowUpRight :size="14"/></ElLink><AppDisclosure><template #title>原文摘录 　 {{ source.excerpts.length }}</template><blockquote v-for="excerpt in source.excerpts" :key="excerpt.id">{{ excerpt.content }}</blockquote></AppDisclosure></Surface><p v-if="!result?.materials?.length">暂无原文摘录</p></section></Surface></main>
</div>
<AppDialog v-model:open="confirmOpen" title="确认用于备课" description="请核对下方替换内容，确认后保存草稿，不会发布。"><div class="planning-confirm"><p v-if="draftState?.sourceVersion">来源课时 v{{ job?.input?.lesson?.version }} 　 当前发布 v{{ draftState.sourceVersion.version }}</p><div v-if="!job?.input?.regenerateBlockId" class="planning-diff-goal"><h3>教学目标</h3><p>当前：{{ draftState?.goal }}</p><p>新建议：{{ edited?.goal }}</p></div><Surface data-ui="card" v-for="block in (edited?.blocks||[]).filter(b=>!job?.input?.regenerateBlockId||b.id===job.input.regenerateBlockId)" :key="block.id" class="planning-diff"><h3>{{ block.title }}</h3><div><section><strong>当前内容</strong><p>{{ draftState?.blocks?.find(b=>b.id===block.id)?.content||'无对应活动' }}</p><p v-for="(label,key) in {studentTask:'学生任务',teacherQuestion:'关键提问',studentResponse:'预设回应',adjustment:'困难处理'}" :key="key">{{ label }}：{{ draftState?.blocks?.find(b=>b.id===block.id)?.[key]||'未填写' }}</p></section><section><strong>新建议</strong><p>{{ block.content }}</p><p v-for="(label,key) in {studentTask:'学生任务',teacherQuestion:'关键提问',studentResponse:'预设回应',adjustment:'困难处理'}" :key="key">{{ label }}：{{ block[key]||'未填写' }}</p></section></div></Surface><p>{{ job?.input?.regenerateBlockId?'只替换选定活动，其他活动及目标保留。':'替换当前目标和全部活动；下方展示新旧内容。' }}题目、教学安排、引用和已发布任务保留，不会自动发布。</p><AppAlert type="error" v-if="error" role="alert" class="form-error">{{ error }}</AppAlert><AppButton :disabled="saving" @click="confirmDraft">{{ saving?'保存中…':'确认保存到备课草稿' }}</AppButton></div></AppDialog>
</template>
